def _exact_decimal(text):
    """在高精度 localcontext 下解析文本，绝不改变调用方全局 context。"""
    from decimal import localcontext

    digits = sum(1 for ch in text if ch.isdigit())
    with localcontext() as ctx:
        ctx.prec = max(28, digits + 10)
        ctx.Emax = 999999
        ctx.Emin = -999999
